head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};

scwin.checkEl = function(id1, id2) {
	if (scwin.__getDom($p.id + id1)) {
		return true;
	} else if (scwin.__getDom($p.id + id2)) {
		return true;
	}
	return false;
};

scwin.checktype1 = function() {
	return typeof wfm1;
};

scwin.checktype2 = function() {
	return typeof (document.getElementById('wfm1_selectbox1') || document.getElementById('mf_wfm1_selectbox1'));
};

// SKT-380: wframe(scope) 안 컴포넌트의 dataList 바인딩 - selectbox itemset 표시값 + input ref(dataList rowPosition 행 값). 2026-11
scwin.checkBind = function() {
	var w = $p.getComponentById('wfm1').getWindow();
	var dl = w.$p.getComponentById('dst_ordsb0510030t01_out01');
	dl.setJSON([{ svc_mgmt_num: 'SVC01' }]);
	dl.setRowPosition(0);
	return w.$p.getComponentById('selectbox1').getText() + '|' + w.$p.getComponentById('input1').getValue();
};
scwin.checktype3 = function() {
	return typeof (document.getElementById('wfm1_input1') || document.getElementById('mf_wfm1_input1'));
};
